    const items = [...document.querySelectorAll(".item")];
    const subtotalEl = document.getElementById("subtotal");
    const deliveryEl = document.getElementById("delivery");
    const vatEl = document.getElementById("vat");
    const discountEl = document.getElementById("discount");
    const totalEl = document.getElementById("total");
    const cartCountEl = document.getElementById("cartCount");
    const promoInput = document.getElementById("promoCode");
    const promoMessage = document.getElementById("promoMessage");
    const toast = document.getElementById("toast");

    const deliveryFee = 7;
    let discount = 0;
    let toastTimer;

    function formatMoney(value) {
      return `${value.toLocaleString("en-AE", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })} AED`;
    }

    function updateSummary() {
      let subtotal = 0;
      let count = 0;

      items.forEach((item) => {
        const quantity = Number(item.querySelector(".quantity").textContent);
        const unitPrice = Number(item.dataset.price);
        const lineTotal = quantity * unitPrice;

        subtotal += lineTotal;
        count += quantity;
        item.querySelector(".price bdi").textContent = formatMoney(lineTotal);
        item.querySelector('[data-action="decrease"]').disabled = quantity <= 1;
      });

      const taxable = Math.max(0, subtotal - discount);
      const vat = taxable * 0.05;
      const total = taxable + vat + deliveryFee;

      subtotalEl.textContent = formatMoney(subtotal);
      deliveryEl.textContent = formatMoney(deliveryFee);
      vatEl.textContent = formatMoney(vat);
      discountEl.textContent = `−${formatMoney(discount)}`;
      totalEl.textContent = formatMoney(total);
      cartCountEl.textContent = count;
    }

    function showToast(message) {
      clearTimeout(toastTimer);
      toast.textContent = message;
      toast.classList.add("show");
      toastTimer = setTimeout(() => toast.classList.remove("show"), 2600);
    }

    items.forEach((item) => {
      item.querySelectorAll(".stepper button").forEach((button) => {
        button.addEventListener("click", () => {
          const quantityEl = item.querySelector(".quantity");
          let quantity = Number(quantityEl.textContent);

          if (button.dataset.action === "increase") {
            quantity += 1;
          } else if (quantity > 1) {
            quantity -= 1;
          }

          quantityEl.textContent = quantity;
          discount = 0;
          promoMessage.textContent = "";
          promoMessage.className = "promo-message";
          updateSummary();
        });
      });
    });

    document.getElementById("applyPromo").addEventListener("click", () => {
      const code = promoInput.value.trim().toUpperCase();

      if (!code) {
        promoMessage.textContent = "أدخل رمز الخصم أولًا.";
        promoMessage.className = "promo-message error";
        return;
      }

      if (code === "FRESH10") {
        discount = 5;
        promoMessage.textContent = "تم تطبيق خصم 5.00 AED على طلبك.";
        promoMessage.className = "promo-message success";
      } else {
        discount = 0;
        promoMessage.textContent = "رمز الخصم غير صالح. جرّب FRESH10.";
        promoMessage.className = "promo-message error";
      }

      updateSummary();
    });

    promoInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        document.getElementById("applyPromo").click();
      }
    });

    document.getElementById("placeOrder").addEventListener("click", () => {
      showToast("تم استلام طلبك بنجاح. جارٍ تأكيد التفاصيل.");
    });

    updateSummary();
  </script>
