    }

    .icon-button:focus-visible {
      box-shadow: 0 0 0 3px rgba(12, 143, 97, 0.22);
    }

    .icon-button svg {
      width: 24px;
      height: 24px;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
