      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }

    .stepper {
      display: grid;
      grid-template-columns: 34px 30px 34px;
      align-items: center;
      overflow: hidden;
      border: 1px solid #cfd8d3;
      border-radius: 999px;
      background: white;
    }

    .stepper button {
      width: 34px;
      height: 34px;
      padding: 0;
      border: 0;
