    .promo-message.success {
      color: var(--green-800);
    }

    .promo-message.error {
      color: var(--danger);
    }

    .summary {
      padding: 20px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: #fbfcfb;
    }

    .summary-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-block-end: 11px;
      color: #45514c;
      font-size: 15px;
