    .summary-row:last-child {
      margin-block-end: 0;
    }

    .summary-row span:last-child {
      direction: ltr;
      unicode-bidi: isolate;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }

    .summary .divider {
      height: 1px;
      margin: 15px 0;
      background: var(--line);
    }

    .total-row {
      color: var(--ink);
      font-size: 17px;
      font-weight: 700;
    }

    .total-row span:last-child {
      color: var(--green-800);
      font-size: 20px;
    }

    .payment-note {
      margin: 12px 2px 0;
      color: var(--muted);
      font-size: 14px;
    }

    .place-order {
      width: 100%;
      min-height: 56px;
      margin-block-start: 24px;
      padding: 12px 20px;
      border: 0;
      border-radius: 14px;
      color: white;
      background: var(--green-700);
      box-shadow: 0 8px 20px rgba(7, 93, 64, 0.2);
      font-size: 17px;
      font-weight: 700;
      transition: transform 0.15s ease, background 0.15s ease;
    }

    .place-order:hover {
      background: var(--green-800);
    }

    .place-order:active {
      transform: scale(0.985);
    }

    .place-order:focus-visible,
    .apply-button:focus-visible {
      outline: 3px solid rgba(12, 143, 97, 0.3);
      outline-offset: 2px;
    }

    .secure-note {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      margin: 12px 0 0;
      color: var(--muted);
      font-size: 14px;
    }

    .secure-note svg {
      width: 16px;
      height: 16px;
      fill: none;
      stroke: currentColor;
      stroke-width: 2;
    }

    .toast {
      position: fixed;
      inset-inline: 20px;
      inset-block-end: 20px;
      z-index: 30;
      max-width: 420px;
      margin: auto;
      padding: 13px 18px;
      border-radius: 12px;
      color: white;
      background: #24312c;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.22);
      text-align: center;
      opacity: 0;
      pointer-events: none;
      transform: translateY(16px);
      transition: opacity 0.2s ease, transform 0.2s ease;
    }

    .toast.show {
      opacity: 1;
      transform: translateY(0);
    }

    @media (min-width: 700px) {
      body {
        padding: 24px 0;
      }

      .app {
        min-height: calc(100vh - 48px);
        border-radius: 24px;
        box-shadow: 0 18px 60px rgba(25, 43, 35, 0.1);
        overflow: hidden;
      }

      .topbar {
        border-radius: 24px 24px 0 0;
      }
    }
  </style>
</head>
